32	    console.log(`Session started: ${sessionId}`);
33	    return session;
34	  },
35	
36	  restore: () => {
37	    if (!fs.existsSync(SESSION_FILE)) {
38	      console.log('No session to restore');
39	      return null;
40	    }
41	
42	    const session = JSON.parse(fs.readFileSync(SESSION_FILE, 'utf-8'));
43	    session.restoredAt = new Date().toISOString();
44	    fs.writeFileSync(SESSION_FILE, JSON.stringify(session, null, 2));
45	
46	    console.log(`Session restored: ${session.id}`);
47	    return session;
48	  },
49	
50	  end: () => {
51	    if (!fs.existsSync(SESSION_FILE)) {
52	      console.log('No active session');
53	      return null;
54	    }
55	
56	    const session = JSON.parse(fs.readFileSync(SESSION_FILE, 'utf-8'));
57	    session.endedAt = new Date().toISOString();
58	    session.duration = Date.now() - new Date(session.startedAt).getTime();
59	
60	    // Archive session
61	    const archivePath = path.join(SESSION_DIR, `${session.id}.json`);
62	    fs.writeFileSync(archivePath, JSON.stringify(session, null, 2));
63	    fs.unlinkSync(SESSION_FILE);
64	
65	    console.log(`Session ended: ${session.id}`);
66	    console.log(`Duration: ${Math.round(session.duration / 1000 / 60)} minutes`);
67	    console.log(`Metrics: ${JSON.stringify(session.metrics)}`);
68	
69	    return session;
70	  },
71	
72	  status: () => {
73	    if (!fs.existsSync(SESSION_FILE)) {
74	      console.log('No active session');
75	      return null;
76	    }
77	
78	    const session = JSON.parse(fs.readFileSync(SESSION_FILE, 'utf-8'));
79	    const duration = Date.now() - new Date(session.startedAt).getTime();
80	
81	    console.log(`Session: ${session.id}`);
82	    console.log(`Started: ${session.startedAt}`);
83	    console.log(`Duration: ${Math.round(duration / 1000 / 60)} minutes`);
84	    console.log(`Metrics: ${JSON.stringify(session.metrics)}`);
85	
86	    return session;
87	  },
88	
89	  update: (key, value) => {
90	    if (!fs.existsSync(SESSION_FILE)) {
91	      console.log('No active session');
92	      return null;
93	    }
94	
95	    const session = JSON.parse(fs.readFileSync(SESSION_FILE, 'utf-8'));
96	    session.context[key] = value;
97	    session.updatedAt = new Date().toISOString();
98	    fs.writeFileSync(SESSION_FILE, JSON.stringify(session, null, 2));
99	
100	    return session;
101	  },
102	
103	  metric: (name) => {
104	    if (!fs.existsSync(SESSION_FILE)) {
105	      return null;
106	    }
107	
108	    const session = JSON.parse(fs.readFileSync(SESSION_FILE, 'utf-8'));
109	    if (session.metrics[name] !== undefined) {
110	      session.metrics[name]++;
111	      fs.writeFileSync(SESSION_FILE, JSON.stringify(session, null, 2));
112	    }
113	
114	    return session;
115	  },
116	};
