380	  static getEffectiveCpuCount(): number {
381	    // 1. Try cgroup v2: /sys/fs/cgroup/cpu.max
382	    try {
383	      const cpuMax = readFileSync('/sys/fs/cgroup/cpu.max', 'utf8').trim();
384	      const [quotaStr, periodStr] = cpuMax.split(' ');
385	      if (quotaStr !== 'max') {
386	        const quota = parseInt(quotaStr, 10);
387	        const period = parseInt(periodStr, 10);
388	        if (quota > 0 && period > 0) return Math.ceil(quota / period);
389	      }
390	    } catch { /* not in cgroup v2 */ }
391	
392	    // 2. Try cgroup v1: /sys/fs/cgroup/cpu/cpu.cfs_quota_us
393	    try {
394	      const quota = parseInt(readFileSync('/sys/fs/cgroup/cpu/cpu.cfs_quota_us', 'utf8').trim(), 10);
395	      const period = parseInt(readFileSync('/sys/fs/cgroup/cpu/cpu.cfs_period_us', 'utf8').trim(), 10);
396	      if (quota > 0 && period > 0) return Math.ceil(quota / period);
397	    } catch { /* not in cgroup v1 */ }
398	
399	    // 3. Fallback to os.cpus().length
400	    return cpus().length || 1;
401	  }
