453	  /**
454	   * Curate MEMORY.md to stay under the line limit.
455	   * Groups entries by category and prunes low-confidence items.
456	   */
457	  async curateIndex(): Promise<void> {
458	    await this.ensureMemoryDir();
459	
460	    // Collect summaries from all topic files
461	    const sections: Record<string, string[]> = {};
462	
463	    for (const [category, filename] of Object.entries(this.config.topicMapping)) {
464	      const topicPath = path.join(this.config.memoryDir, filename as string);
465	      if (existsSync(topicPath)) {
466	        const content = await fs.readFile(topicPath, 'utf-8');
467	        const summaries = extractSummaries(content);
468	        if (summaries.length > 0) {
469	          sections[category] = summaries;
470	        }
471	      }
472	    }
473	
474	    // Fix for #1556: if no topic files matched (e.g. the memory folder uses
475	    // Claude Code's native `<type>_<topic>.md` convention rather than the
476	    // hardcoded DEFAULT_TOPIC_MAPPING filenames), do NOT overwrite the
477	    // existing MEMORY.md with a one-line stub. A `curate` operation must be
478	    // non-destructive when there is nothing to curate.
479	    if (Object.keys(sections).length === 0) {
480	      this.emit('index:skipped', { reason: 'no-matching-topic-files' });
481	      return;
482	    }
483	
484	    // ADR-049: Use graph PageRank to prioritize sections
485	    let sectionOrder: string[] | undefined;
486	    if (this.memoryGraph) {
487	      const topNodes = this.memoryGraph.getTopNodes(20);
488	      const categoryCounts = new Map<string, number>();
489	      for (const node of topNodes) {
490	        const cat = node.community || 'general';
491	        categoryCounts.set(cat, (categoryCounts.get(cat) || 0) + 1);
492	      }
493	      sectionOrder = [...categoryCounts.entries()]
494	        .sort((a, b) => b[1] - a[1])
495	        .map(([cat]) => cat)
496	        .filter((cat) => sections[cat]);
497	    }
498	
499	    // Prune sections before building the index to avoid O(n^2) rebuild loop
500	    const budget = this.config.maxIndexLines;
501	    pruneSectionsToFit(sections, budget, this.config.pruneStrategy);
502	
503	    // Build the final index (with optional graph-aware ordering)
504	    const lines = buildIndexLines(
505	      sections,
506	      this.config.topicMapping as Record<string, string>,
507	      sectionOrder,
508	    );
509	
510	    await fs.writeFile(this.getIndexPath(), lines.join('\n'), 'utf-8');
511	    this.emit('index:curated', { lines: lines.length });
512	  }
